<!--
    AgentTer - PowerShell Shell Integration Profile

    This script is injected into each terminal session at startup.
    It emits DCS (Device Control String) escape sequences to communicate
    command boundaries (preexec/precmd) and metadata back to the terminal.

    Protocol:
    - ESC P {json} ESC \  - DCS sequence with JSON payload
    - Hooks: Preexec (before command), Precmd (after prompt), CommandFinished (exit code)
-->

# AgentTer shell integration for PowerShell
# Generated by AgentTer - do not edit manually

$Global:__AGENTTER_PREV_PWD = $PWD.Path
$Global:__AGENTTER_LAST_COMMAND = ""

# Emit a DCS hook to the terminal
function __agentter_emit_hook {
    param([string]$hook, [hashtable]$value)
    try {
        $json = @{ hook = $hook; value = $value } | ConvertTo-Json -Compress -Depth 3
        # Escape control characters that could break DCS
        $payload = $json -replace '([\u0000-\u001f\u007f-\u009f])', ''
        Write-Host -NoNewline "`eP$payload`e\"
    } catch {
        # Never break the shell on integration errors
    }
}

# Called before command execution (hooked via prompt override)
function __agentter_preexec {
    param([string]$command)
    if ([string]::IsNullOrWhiteSpace($command)) { return }
    $Global:__AGENTTER_LAST_COMMAND = $command
    __agentter_emit_hook -hook 'Preexec' -value @{ command = $command }
}

# Called after command completes and before new prompt
function __agentter_precmd {
    $pwd = $PWD.Path
    if ($pwd -ne $Global:__AGENTTER_PREV_PWD) {
        $Global:__AGENTTER_PREV_PWD = $pwd
    }
    $gitBranch = ''
    try {
        $gitBranch = (git rev-parse --abbrev-ref HEAD 2>$null)
    } catch {}

    __agentter_emit_hook -hook 'Precmd' -value @{
        pwd = $pwd
        gitBranch = if ($gitBranch) { $gitBranch } else { "" }
    }

    __agentter_emit_hook -hook 'CommandFinished' -value @{
        exitCode = if ($LASTEXITCODE) { $LASTEXITCODE } else { 0 }
    }
}

# Override prompt function to hook into command lifecycle
$OriginalPrompt = Get-Content function:\prompt
function prompt {
    # Get last executed command from history
    $lastCmd = Get-History -Count 1 | ForEach-Object { $_.CommandLine }
    if ($lastCmd -and $lastCmd -ne $Global:__AGENTTER_LAST_COMMAND) {
        __agentter_preexec -command $lastCmd
    }

    # Emit precmd (prompt metadata)
    __agentter_precmd

    # Call original prompt
    try {
        & $OriginalPrompt
    } catch {
        "PS $($PWD.Path)> "
    }
}

# Signal that integration is active
Write-Host ""
